<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {message,Modal} from 'ant-design-vue'
import {api,errorMessage} from '../../api/http'
import {useAuthStore} from '../../stores/auth'
import {sourceList,sourceDetail,sourceTypes,sourceCatalogs,sourcePolicies,sourceMutation,emptyConfiguration,rawFormat,type DataSource,type Configuration,type SourceField,type SourceJoin,type Catalog,type DocumentType,type Policy,type Metadata,type Validation} from '../../api/printDataSources'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),busy=ref(false),error=ref(''),loading=ref(true)
const isList=computed(()=>route.name==='print-data-sources'),readonly=computed(()=>route.meta.mode==='view'),canManage=computed(()=>auth.can('print:source:manage'))
const items=ref<DataSource[]>([]),total=ref(0),page=ref(1),keyword=ref(''),queryType=ref<string>(),queryStatus=ref<string>(),includeDeleted=ref(false)
const row=ref<DataSource|null>(null),config=ref<Configuration>(emptyConfiguration()),sourceCode=ref(''),types=ref<string[]>([]),catalogs=ref<Catalog[]>([]),choices=ref<DocumentType[]>([]),policies=ref<Policy[]>([]),reason=ref(''),step=ref(2),selected=ref(''),fieldSearch=ref(''),groupFilter=ref<string>(),savedSnapshot=ref(''),proof=ref<Validation|null>(null),samples=ref<Record<string,string>>({})
const relationOpen=ref(false),joinDraft=ref<SourceJoin|null>(null),relationId=ref(''),relationChoice=ref(''),modalError=ref(''),fieldOpen=ref(false),fieldDraft=ref<SourceField|null>(null),fieldEditId=ref('')
const metaOpen=ref(false),metaType=ref(''),metaVersion=ref(0),metaPolicy=ref(''),metaRoots=ref<string[]>([]),metaFilters=ref<Metadata['fixedTypeFilters']>([]),metaReason=ref(''),templateOpen=ref(false),templateType=ref<string>(),templateFields=ref<{key:string;label:string;group:string}[]>([]),templateError=ref('')
const copy=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const stableKeys=/^[A-Za-z][A-Za-z0-9]{0,79}$/
const signature=()=>JSON.stringify({configuration:config.value,sourceCode:sourceCode.value,businessTypes:types.value})
const dirty=computed(()=>!isList.value&&!loading.value&&signature()!==savedSnapshot.value)
const chosen=computed(()=>config.value.fields.find(f=>f.fieldId===selected.value))
const nodes=computed(()=>[{nodeId:'main',label:'主表',catalogId:config.value.mainCatalogId},...config.value.joins])
const catalog=(id:string)=>catalogs.value.find(c=>c.catalogId===id)
const nodeLabel=(id:string)=>id==='main'?catalog(config.value.mainCatalogId)?.label:config.value.joins.find(j=>j.nodeId===id)?.label
const sourceLabel=(f:SourceField)=>`${nodeLabel(f.sourcePath.nodeId)??'来源失效'} · ${catalog(nodes.value.find(n=>n.nodeId===f.sourcePath.nodeId)?.catalogId??'')?.fields.find(x=>x.fieldId===f.sourcePath.catalogFieldId)?.label??f.sourcePath.catalogFieldId}`
function datasetFor(nodeId:string){const seen=new Set<string>();while(nodeId!=='main'){if(seen.has(nodeId))return null;seen.add(nodeId);const j=config.value.joins.find(n=>n.nodeId===nodeId);if(!j)return null;if(j.cardinality==='1:N')return j.datasetKey;nodeId=j.parentNodeId}return null}
const fieldOptions=computed(()=>nodes.value.flatMap(n=>(catalog(n.catalogId)?.fields??[]).map(f=>({value:`${n.nodeId}|${f.fieldId}`,label:`${nodeLabel(n.nodeId)} · ${f.label}`,field:f,node:n.nodeId}))))
const filteredFields=computed(()=>config.value.fields.filter(f=>(f.label+f.fieldKey).includes(fieldSearch.value)&&(!groupFilter.value||f.dataGroup===groupFilter.value)))
const groups=computed(()=>[...new Set(config.value.fields.map(f=>f.dataGroup))])
const roots=computed(()=>catalogs.value.filter(c=>!types.value.length||types.value.every(t=>choices.value.find(d=>d.value===t)?.metadata?.compatibleMainCatalogIds.includes(c.catalogId))))
const possibleRelations=computed(()=>catalog(nodes.value.find(n=>n.nodeId===joinDraft.value?.parentNodeId)?.catalogId??'')?.relations??[])
const validProof=computed(()=>!dirty.value&&proof.value?.result==='PASS'&&!proof.value.invalidatedAt&&Date.parse(proof.value.expiresAt)>Date.now())
const typeLabel=(t:string)=>choices.value.find(d=>d.value===t)?.label??t
const typeName=(t:string)=>({TEXT:'文本',NUMBER:'数值',DATE:'日期',DATETIME:'日期时间',BOOLEAN:'布尔'}[t]??t)
function fail(e:unknown){error.value=errorMessage(e)}
async function loadList(){busy.value=true;try{const data=await sourceList({page:page.value-1,size:20,keyword:keyword.value,businessType:queryType.value,status:queryStatus.value,includeDeleted:includeDeleted.value});items.value=data.items;total.value=data.total;error.value=''}catch(e){fail(e)}finally{busy.value=false}}
function reset(){keyword.value='';queryType.value=undefined;queryStatus.value=undefined;page.value=1;void loadList()}
async function initialize(){loading.value=true;try{const [c,p,d]=await Promise.all([sourceCatalogs(),sourcePolicies(),sourceTypes(typeof route.params.id==='string'?route.params.id:undefined)]);catalogs.value=c.entities;policies.value=p;choices.value=d;if(isList.value)await loadList();else if(typeof route.params.id==='string'){row.value=await sourceDetail(route.params.id);config.value=copy((row.value.draft??row.value.published)?.configuration??emptyConfiguration());sourceCode.value=row.value.sourceCode;types.value=row.value.businessTypes.map(t=>t.businessType);proof.value=row.value.validation;step.value=2;selected.value=config.value.fields[0]?.fieldId??''}else{row.value=null;config.value=emptyConfiguration();sourceCode.value='';types.value=[];proof.value=null;step.value=0}reason.value='';savedSnapshot.value=signature();error.value=''}catch(e){fail(e)}finally{loading.value=false}}
watch(()=>route.fullPath,initialize);onMounted(initialize)
watch([config,types],()=>{if(!loading.value&&signature()!==savedSnapshot.value)proof.value=null},{deep:true})
const confirmNavigation=()=>{if(!dirty.value)return true;return new Promise<boolean>(resolve=>Modal.confirm({title:'放弃未保存的修改？',content:'本次修改尚未保存。',okText:'放弃并离开',cancelText:'继续编辑',onOk:()=>resolve(true),onCancel:()=>resolve(false)}))};onBeforeRouteLeave(confirmNavigation);onBeforeRouteUpdate(confirmNavigation)
async function save(){if(busy.value||readonly.value)return;busy.value=true;try{if(!sourceCode.value||!config.value.sourceName||!reason.value.trim())throw new Error('请填写编码、名称和变更原因');const data={sourceName:config.value.sourceName,businessTypes:types.value,configuration:config.value,reason:reason.value,...(row.value?{expectedVersion:row.value.versionNo}:{sourceCode:sourceCode.value})};const result=await sourceMutation<DataSource>(row.value?`/printing/data-sources/${row.value.id}/draft`:'/printing/data-sources',row.value?'PUT':'POST',data,row.value?.versionNo);row.value=result;config.value=copy(result.draft!.configuration);savedSnapshot.value=signature();proof.value=null;choices.value=await sourceTypes(result.id);message.success('草稿已保存');if(route.meta.mode==='create')await router.replace(`/admin/print-data-sources/${result.id}/edit`)}catch(e){fail(e)}finally{busy.value=false}}
async function validate(){if(busy.value||!row.value||dirty.value)return;busy.value=true;try{proof.value=await sourceMutation<Validation>(`/printing/data-sources/${row.value.id}/validate`,'POST',{expectedVersion:row.value.versionNo,samples:types.value.map(t=>({businessType:t,recordId:samples.value[t]??''})),reason:reason.value},row.value.versionNo);step.value=3;error.value='';message[proof.value.result==='PASS'?'success':'warning'](proof.value.result==='PASS'?'真实样本校验通过':'校验未通过')}catch(e){fail(e)}finally{busy.value=false}}
async function publish(){if(busy.value||!row.value||!validProof.value||!row.value.draft)return;Modal.confirm({title:'发布当前已校验版本？',content:`草稿哈希 ${row.value.draft.configHash}。已发布历史版本保持固定引用。`,onOk:async()=>{busy.value=true;try{const source=row.value!;row.value=await sourceMutation<DataSource>(`/printing/data-sources/${source.id}/publish`,'POST',{expectedVersion:source.versionNo,revisionId:source.draft!.id,configHash:source.draft!.configHash,validationId:proof.value!.id,reason:reason.value},source.versionNo);savedSnapshot.value=signature();message.success('数据源已发布');await initialize()}catch(e){fail(e)}finally{busy.value=false}}})}
function mainChanged(){config.value.joins=[];config.value.fields=[];selected.value=''}
function openJoin(j?:SourceJoin){relationId.value=j?.nodeId??'';joinDraft.value=j?copy(j):{nodeId:`node${Date.now()}`,label:'',parentNodeId:'main',catalogId:'',knownRelationId:'',cardinality:'N:1',keys:[],datasetKey:null,displayOrder:config.value.joins.length,sort:[]};relationChoice.value=j?.knownRelationId??'';modalError.value='';relationOpen.value=true}
function chooseRelation(value:string){const rel=possibleRelations.value.find(r=>r.relationId===value);if(!rel||!joinDraft.value)return;Object.assign(joinDraft.value,{knownRelationId:rel.relationId,catalogId:rel.targetCatalogId,cardinality:rel.cardinality,keys:copy(rel.keys),label:catalog(rel.targetCatalogId)?.label??'',datasetKey:rel.cardinality==='1:N'?joinDraft.value.datasetKey??`detail${config.value.joins.length+1}`:null})}
function saveJoin(){const j=joinDraft.value;if(!j)return;if(!j.label||!j.knownRelationId||j.cardinality==='1:N'&&!stableKeys.test(j.datasetKey??'')){modalError.value='请选择受控关联并填写名称；集合标识仅允许字母数字';return}const index=config.value.joins.findIndex(n=>n.nodeId===relationId.value);if(index<0)config.value.joins.push(copy(j));else{config.value.joins[index]=copy(j);for(const f of config.value.fields){const group=datasetFor(f.sourcePath.nodeId);f.datasetKey=group;f.dataGroup=group??'MAIN'}}relationOpen.value=false}
function deleteJoin(j:SourceJoin){Modal.confirm({title:`删除关联“${j.label}”？`,content:'同时移除子关联及其字段，保存草稿后生效。',onOk:()=>{const remove=new Set([j.nodeId]);let changed=true;while(changed){changed=false;for(const n of config.value.joins)if(remove.has(n.parentNodeId)&&!remove.has(n.nodeId)){remove.add(n.nodeId);changed=true}}config.value.joins=config.value.joins.filter(n=>!remove.has(n.nodeId));config.value.fields=config.value.fields.filter(f=>!remove.has(f.sourcePath.nodeId));selected.value=config.value.fields[0]?.fieldId??''}})}
function openField(f?:SourceField){fieldEditId.value=f?.fieldId??'';fieldDraft.value=f?copy(f):{fieldId:`F${Date.now()}`,fieldKey:'',label:'',dataType:'TEXT',sourcePath:{nodeId:'main',catalogFieldId:''},dataGroup:'MAIN',datasetKey:null,available:true,format:rawFormat(),missing:'ERROR',defaultValue:null,displayOrder:config.value.fields.length};modalError.value='';fieldOpen.value=true}
function fieldSource(value:string,f:SourceField){const option=fieldOptions.value.find(o=>o.value===value);if(!option)return;f.sourcePath={nodeId:option.node,catalogFieldId:option.field.fieldId};f.dataType=option.field.dataType;f.label=option.field.label;f.datasetKey=datasetFor(option.node);f.dataGroup=f.datasetKey??'MAIN';f.format=rawFormat();f.defaultValue=null;if(!fieldEditId.value&&!f.fieldKey)f.fieldKey=option.field.fieldId.replace(/[^A-Za-z0-9]/g,'')}
function saveField(){const f=fieldDraft.value;if(!f)return;if(!f.label||!stableKeys.test(f.fieldKey)||!f.sourcePath.catalogFieldId||config.value.fields.some(x=>x.fieldKey===f.fieldKey&&x.fieldId!==fieldEditId.value)){modalError.value='请填写中文名、唯一字母数字稳定键并选择来源字段';return}const index=config.value.fields.findIndex(x=>x.fieldId===fieldEditId.value);if(index<0)config.value.fields.push(copy(f));else config.value.fields[index]=copy(f);selected.value=f.fieldId;fieldOpen.value=false}
function deleteField(f:SourceField){Modal.confirm({title:`删除字段“${f.label}”？`,onOk:()=>{config.value.fields=config.value.fields.filter(x=>x.fieldId!==f.fieldId);selected.value=config.value.fields[0]?.fieldId??''}})}
function formatChanged(value:string,f:SourceField){f.format=value==='NUMBER'?{kind:value,scale:2,roundingMode:'HALF_UP',dateStyle:null}:value==='DATE'?{kind:value,scale:null,roundingMode:null,dateStyle:'DATE_ONLY'}:rawFormat()}
function openMetadata(t?:string){metaType.value=t??choices.value[0]?.value??'';loadMeta();metaReason.value='';modalError.value='';metaOpen.value=true}
function loadMeta(){const m=choices.value.find(t=>t.value===metaType.value)?.metadata;metaVersion.value=m?.versionNo??0;metaPolicy.value=m?.authorizationPolicyRef??'';metaRoots.value=[...(m?.compatibleMainCatalogIds??[])];metaFilters.value=copy(m?.fixedTypeFilters??[])}
async function saveMeta(){if(busy.value)return;busy.value=true;try{if(!metaReason.value.trim())throw new Error('请填写元数据变更原因');const data={expectedVersion:metaVersion.value,authorizationPolicyRef:metaPolicy.value,compatibleMainCatalogIds:metaRoots.value,fixedTypeFilters:metaFilters.value,reason:metaReason.value};await sourceMutation<Metadata>(`/printing/document-types/${metaType.value}/metadata`,'PUT',data,metaVersion.value);choices.value=await sourceTypes(row.value?.id);proof.value=null;metaOpen.value=false;message.success('单据元数据已保存')}catch(e){modalError.value=errorMessage(e)}finally{busy.value=false}}
watch(templateType,async t=>{templateFields.value=[];templateError.value='';if(!t)return;try{const data=await api<{definitions:{key:string;label:string;group:string}[]}>({url:'/printing/fields',params:{businessType:t,printType:'DOCUMENT'}});templateFields.value=data.definitions}catch(e){templateError.value=errorMessage(e)}})
const columns=(data:Record<string,unknown>[])=>Object.keys(data[0]??{}).filter(k=>!Array.isArray(data[0]?.[k])).map(k=>({title:config.value.fields.find(f=>f.fieldKey===k)?.label??(({modeLabel:'打印状态',reportNo:'单据编号'} as Record<string,string>)[k]??k),dataIndex:k,key:k}))
function details(data:Record<string,unknown>){return Object.entries(data).filter(([,v])=>Array.isArray(v)) as [string,Record<string,unknown>[]][]}
async function lifecycle(source:DataSource,action:string){Modal.confirm({title:action==='restore'?'恢复未发布草稿（不恢复类型绑定）？':action==='delete'?'删除未发布草稿？':action==='deactivate'?'停用数据源？':'重新启用数据源？',content:'操作使用当前版本并记录审计；依赖及权限由服务端复核。',onOk:async()=>{try{await sourceMutation(`/printing/data-sources/${source.id}${action==='delete'?'':`/${action}`}`,action==='delete'?'DELETE':'POST',{expectedVersion:source.versionNo,reason:'打印数据源维护（操作确认）'},source.versionNo);await loadList()}catch(e){fail(e)}}})}
</script>
<template>
<section class="admin-page master-page source-page" data-ui-template="T1">
 <a-alert v-if="error" class="notice" type="error" show-icon :message="error"/>
 <template v-if="isList">
 <header class="admin-page-header"><div><h1>打印数据源配置</h1><p>受控目录、类型唯一绑定与不可变发布版本。</p></div><a-space><a-button v-if="canManage" @click="openMetadata()">单据元数据</a-button><a-button @click="templateOpen=true">模板字段预览</a-button><a-button v-if="canManage" type="primary" @click="router.push('/admin/print-data-sources/new')">＋ 新增数据源</a-button></a-space></header>
 <section class="query-section"><h2>查询条件</h2><form class="source-query" @submit.prevent="page=1;loadList()"><label class="form-cell"><span class="field-label">名称或编码</span><a-input v-model:value="keyword" allow-clear/></label><label class="form-cell"><span class="field-label">单据类型</span><a-select v-model:value="queryType" allow-clear :options="choices.map(d=>({value:d.value,label:d.label}))"/></label><label class="form-cell"><span class="field-label">状态</span><a-select v-model:value="queryStatus" allow-clear :options="[{value:'ENABLED',label:'启用'},{value:'DISABLED',label:'停用'}]"/></label><a-checkbox v-if="canManage" v-model:checked="includeDeleted" @change="page=1;loadList()">含已删除草稿</a-checkbox><a-space><a-button @click="reset">重置</a-button><a-button type="primary" html-type="submit" :loading="busy">查询</a-button></a-space></form></section>
 <section class="result-section"><h2>数据源列表</h2><a-table :data-source="items" row-key="id" :loading="busy||loading" :pagination="{current:page,total,pageSize:20,showSizeChanger:false,onChange:(p:number)=>{page=p;loadList()}}" :scroll="{x:1000}"><a-table-column title="数据源名称" data-index="sourceName"/><a-table-column title="配置编码" data-index="sourceCode"/><a-table-column title="适用单据类型"><template #default="{record}"><a-tag v-for="t in record.businessTypes" :key="t.businessType">{{t.label}}</a-tag></template></a-table-column><a-table-column title="发布状态"><template #default="{record}"><a-tag :color="record.status==='DISABLED'?'default':record.publishedRevisionId?'green':'blue'">{{record.status==='DISABLED'?'已停用':record.publishedRevisionId?'已发布':'草稿'}}</a-tag></template></a-table-column><a-table-column title="操作" :width="260"><template #default="{record}"><a-space><a-button type="link" @click="router.push(`/admin/print-data-sources/${record.id}`)">查看</a-button><a-button v-if="canManage&&!record.deletedAt" type="link" @click="router.push(`/admin/print-data-sources/${record.id}/edit`)">编辑</a-button><a-dropdown><a-button type="link">更多</a-button><template #overlay><a-menu><a-menu-item v-if="canManage" @click="openMetadata(record.businessTypes[0]?.businessType)">类型元数据</a-menu-item><a-menu-item v-if="canManage&&record.deletedAt&&!record.publishedRevisionId" @click="lifecycle(record,'restore')">恢复草稿（清空绑定）</a-menu-item><a-menu-item v-if="auth.can('print:source:publish')&&!record.deletedAt" @click="lifecycle(record,record.status==='DISABLED'?'reactivate':'deactivate')">{{record.status==='DISABLED'?'启用':'停用'}}</a-menu-item><a-menu-item v-if="canManage&&!record.deletedAt&&!record.publishedRevisionId" danger @click="lifecycle(record,'delete')">删除草稿</a-menu-item></a-menu></template></a-dropdown></a-space></template></a-table-column></a-table></section>
 </template>
 <template v-else>
 <header class="source-header"><a-space><a-button type="link" @click="router.push('/admin/print-data-sources')">← 返回列表</a-button><h1>打印数据源配置</h1><a-tag v-if="readonly">查看</a-tag></a-space><a-space><a-button v-if="!readonly" type="primary" :loading="busy" @click="save">保存草稿</a-button><a-button v-if="!readonly" :disabled="!row||dirty||busy" @click="validate">取数校验</a-button><a-button @click="templateOpen=true">模板预览</a-button><a-button @click="router.push('/admin/print-data-sources')">取消</a-button></a-space></header>
 <div class="source-basics"><label class="form-cell"><span class="field-label">数据源名称：</span><a-input v-model:value="config.sourceName" :disabled="readonly" aria-label="数据源名称"/></label><label class="form-cell type-pair"><span class="field-label">适用单据类型：</span><a-select v-model:value="types" mode="multiple" :disabled="readonly" aria-label="适用单据类型" :options="choices.map(d=>({value:d.value,label:d.disabled?`${d.label}（${d.disabledReason}）`:d.label,disabled:d.disabled}))"/></label><span class="muted">已绑定其他数据源的类型不可重复选择</span><span>当前状态：<a-tag>{{row?.status==='DISABLED'?'已停用':row?.published?'已发布 / 编辑草稿':'草稿'}}</a-tag></span></div>
 <a-steps v-model:current="step" class="source-steps" :items="[{title:'基本信息'},{title:'数据表关联'},{title:'字段映射'},{title:'取数校验'}]"/>
 <div class="source-layout"><div class="source-workspace">
 <section v-if="step===0" class="source-section"><h2>基本信息</h2><div class="source-form"><label class="form-cell"><span class="field-label">配置编码：</span><a-input v-model:value="sourceCode" :disabled="readonly||!!row" aria-label="配置编码"/></label><label class="form-cell"><span class="field-label">主表目录：</span><a-select v-model:value="config.mainCatalogId" :disabled="readonly" aria-label="主表目录" :options="roots.map(c=>({value:c.catalogId,label:c.label}))" @change="mainChanged"/></label><label class="form-cell"><span class="field-label">变更原因：</span><a-input v-model:value="reason" :disabled="readonly" aria-label="变更原因"/></label></div><a-alert type="info" show-icon message="主表、关联键和字段只来自受控目录；更换主表将清空未保存的关联及字段。"/><a-alert v-for="t in types.filter(t=>!choices.find(d=>d.value===t)?.metadata)" :key="t" type="warning" :message="`${typeLabel(t)}尚未配置兼容目录和读取授权策略`"/><a-button v-if="canManage&&!readonly" @click="openMetadata(types[0])">配置单据类型元数据</a-button></section>
 <template v-if="step===1||step===2"><section class="source-section"><div class="section-heading"><h2>数据表关联</h2><a-button v-if="!readonly" :disabled="!config.mainCatalogId" @click="openJoin()">＋ 添加关联表</a-button></div><div class="relation-root"><span>主表：</span><strong>{{catalog(config.mainCatalogId)?.label??'请选择主表'}}</strong></div><div class="relation-branches"><div v-for="j in config.joins" :key="j.nodeId" class="relation-line"><span>{{nodeLabel(j.parentNodeId)}}</span><span class="relation-arrow">→ {{j.cardinality}} →</span><a-button @click="!readonly&&openJoin(j)">{{j.label}}</a-button><small v-if="j.datasetKey">集合 {{j.datasetKey}}</small><a-button v-if="!readonly" danger type="link" @click="deleteJoin(j)">删除</a-button></div></div><p class="muted">所有关系使用注册键；多个明细集合独立取数，禁止嵌套 1:N。</p></section>
 <section v-if="step===2" class="source-section"><h2>字段映射 <small>模板按单据类型自动加载可用中文字段。</small></h2><div class="field-query"><label class="form-cell"><span class="field-label">字段名称：</span><a-input v-model:value="fieldSearch" placeholder="输入中文名称或标识" aria-label="字段查询"/></label><label class="form-cell"><span class="field-label">数据分组：</span><a-select v-model:value="groupFilter" allow-clear placeholder="全部" :options="groups.map(g=>({value:g,label:g==='MAIN'?'主信息':g}))"/></label><a-button v-if="!readonly" type="primary" @click="openField()">＋ 添加字段</a-button></div><a-table size="small" :data-source="filteredFields" row-key="fieldId" :pagination="false" :scroll="{x:800}" :custom-row="(f:SourceField)=>({onClick:()=>selected=f.fieldId,class:f.fieldId===selected?'selected-field':''})"><a-table-column title="中文名称" data-index="label"/><a-table-column title="稳定字段标识" data-index="fieldKey"/><a-table-column title="类型"><template #default="{record}">{{typeName(record.dataType)}}</template></a-table-column><a-table-column title="来源字段"><template #default="{record}">{{sourceLabel(record)}}</template></a-table-column><a-table-column title="数据分组"><template #default="{record}">{{record.dataGroup==='MAIN'?'主信息':record.dataGroup}}</template></a-table-column><a-table-column title="模板可用"><template #default="{record}"><a-switch v-model:checked="record.available" :disabled="readonly"/></template></a-table-column><a-table-column title="操作"><template #default="{record}"><a-dropdown v-if="!readonly"><a-button type="link">⋯</a-button><template #overlay><a-menu><a-menu-item @click="openField(record)">编辑</a-menu-item><a-menu-item danger @click="deleteField(record)">删除</a-menu-item></a-menu></template></a-dropdown></template></a-table-column></a-table><a-alert class="contract-note" type="info" show-icon message="一个数据源可绑定多个单据类型；每类型唯一数据源；每模板只绑定一个单据类型。"/></section></template>
 <section v-if="step===3" class="source-section"><h2>取数校验</h2><a-alert type="info" show-icon message="请先保存草稿，按每个绑定类型提供一个当前有权限读取的真实记录 ID；预览不持久保存。"/><div class="source-form"><label v-for="t in types" :key="t" class="form-cell"><span class="field-label">{{typeLabel(t)}}：</span><a-input v-model:value="samples[t]" :disabled="readonly" :aria-label="`${typeLabel(t)}记录标识`" placeholder="真实记录 ID"/></label><label class="form-cell"><span class="field-label">校验原因：</span><a-input v-model:value="reason" :disabled="readonly"/></label></div><a-button v-if="!readonly" type="primary" :disabled="!row||dirty" :loading="busy" @click="validate">执行取数校验</a-button><a-alert v-if="dirty" type="warning" message="存在未保存修改，请先保存草稿。"/><template v-if="proof"><a-alert :type="proof.result==='PASS'?'success':'error'" :message="`校验结果：${proof.result==='PASS'?'通过':'失败'}；有效期至 ${proof.expiresAt}`" show-icon/><div v-for="result in proof.typeResults" :key="result.businessType"><h3>{{typeLabel(result.businessType)}}</h3><a-alert v-for="issue in result.issues" :key="issue.code" type="error" :message="issue.message"/></div><template v-for="preview in proof.preview??[]" :key="preview.businessType"><h3>{{typeLabel(preview.businessType)}} · 主信息</h3><a-table :data-source="[preview.data]" :columns="columns([preview.data])" :pagination="false" :scroll="{x:600}"/><template v-for="[key,data] in details(preview.data)" :key="key"><h3>{{config.joins.find(j=>j.datasetKey===key)?.label??key}} · {{data.length}} 行</h3><a-table :data-source="data" :columns="columns(data)" :pagination="false" :scroll="{x:600}"/></template><details><summary>原始值（与中文显示格式分离）</summary><pre>{{JSON.stringify(preview.rawData,null,2)}}</pre></details></template><p v-if="!proof.previewIncluded" class="muted">重开或幂等重放不返回样本正文，请重新校验获取预览。</p></template><a-empty v-else description="校验通过后才可发布当前明确草稿版本"/></section>
 </div><aside class="source-inspector"><h2>字段属性</h2><template v-if="chosen"><div class="source-form"><label class="form-cell"><span class="field-label">中文名称：</span><a-input v-model:value="chosen.label" :disabled="readonly" aria-label="字段中文名称"/></label><label class="form-cell"><span class="field-label">字段标识：</span><a-input :value="chosen.fieldKey" disabled/></label><label class="form-cell"><span class="field-label">来源字段：</span><a-select :value="`${chosen.sourcePath.nodeId}|${chosen.sourcePath.catalogFieldId}`" :disabled="readonly" :options="fieldOptions" @change="(v:string)=>fieldSource(v,chosen!)"/></label><label class="form-cell"><span class="field-label">数据类型：</span><a-input :value="typeName(chosen.dataType)" disabled/></label><label class="form-cell"><span class="field-label">显示格式：</span><a-select :value="chosen.format.kind" :disabled="readonly" :options="[{value:'RAW',label:'原始显示'},...(chosen.dataType==='NUMBER'?[{value:'NUMBER',label:'数字格式'}]:['DATE','DATETIME'].includes(chosen.dataType)?[{value:'DATE',label:'日期格式'}]:[])]" @change="(v:string)=>formatChanged(v,chosen!)"/></label><label v-if="chosen.format.kind==='NUMBER'" class="form-cell"><span class="field-label">小数位数：</span><a-input-number v-model:value="chosen.format.scale" :disabled="readonly" :min="0" :max="6"/></label><label v-if="chosen.format.kind==='DATE'" class="form-cell"><span class="field-label">日期格式：</span><a-select v-model:value="chosen.format.dateStyle" :disabled="readonly" :options="[{value:'DATE_ONLY',label:'年月日'},{value:'UTC_DATE_TIME',label:'UTC日期时间'}]"/></label><label class="form-cell"><span class="field-label">缺失处理：</span><a-select :value="chosen.missing" @change="(v:string)=>{chosen!.missing=v;chosen!.defaultValue=null}" :disabled="readonly" :options="[{value:'ERROR',label:'缺失阻断'},{value:'EMPTY',label:'留空'},{value:'DEFAULT',label:'指定默认值'}]"/></label><label v-if="chosen.missing==='DEFAULT'" class="form-cell"><span class="field-label">默认值：</span><a-select v-if="chosen.dataType==='BOOLEAN'" v-model:value="chosen.defaultValue" :disabled="readonly" :options="[{value:true,label:'是'},{value:false,label:'否'}]"/><a-input v-else :value="chosen.defaultValue==null?'':String(chosen.defaultValue)" :disabled="readonly" @update:value="(v:string)=>chosen!.defaultValue=v"/></label><label class="form-cell"><span class="field-label">供模板使用：</span><a-switch v-model:checked="chosen.available" :disabled="readonly"/></label></div><div class="inspector-note"><h2>字段说明</h2><p>中文名称与稳定键分离。数字格式仅改变显示，原始精确值保留。</p></div></template><a-empty v-else description="请选择或添加字段"/><div class="publish-panel"><h2>当前状态 <a-tag :color="validProof?'green':undefined">{{validProof?'校验通过':'待校验'}}</a-tag></h2><a-alert :type="validProof?'success':'warning'" show-icon :message="validProof?'当前版本校验通过，可以发布。':'请保存并校验当前版本；任何修改使校验证明失效。'"/><a-button block type="primary" :disabled="readonly||!auth.can('print:source:publish')||!validProof||busy" @click="publish">发布数据源</a-button></div></aside></div>
 </template>
 <a-modal v-model:open="relationOpen" :title="relationId?'编辑关联':'添加关联'" :footer="null"><a-alert v-if="modalError" type="error" :message="modalError"/><div v-if="joinDraft" class="source-form"><label class="form-cell"><span class="field-label">上级数据表：</span><a-select v-model:value="joinDraft.parentNodeId" :options="nodes.filter(n=>n.nodeId!==relationId).map(n=>({value:n.nodeId,label:nodeLabel(n.nodeId)}))" @change="relationChoice='';joinDraft!.knownRelationId=''"/></label><label class="form-cell"><span class="field-label">受控关联：</span><a-select v-model:value="relationChoice" :options="possibleRelations.map(r=>({value:r.relationId,label:`${catalog(r.targetCatalogId)?.label} · ${r.cardinality}`}))" @change="chooseRelation"/></label><label class="form-cell"><span class="field-label">关联名称：</span><a-input v-model:value="joinDraft.label"/></label><label v-if="joinDraft.cardinality==='1:N'" class="form-cell"><span class="field-label">集合稳定键：</span><a-input v-model:value="joinDraft.datasetKey"/></label><p>{{joinDraft.cardinality}} · {{joinDraft.keys.map(k=>`${k.parentFieldId} → ${k.targetFieldId}`).join('，')}}</p></div><div class="modal-actions"><a-button @click="relationOpen=false">取消</a-button><a-button type="primary" @click="saveJoin">保存关联</a-button></div></a-modal>
 <a-modal v-model:open="fieldOpen" :title="fieldEditId?'编辑字段':'添加字段'" :footer="null"><a-alert v-if="modalError" type="error" :message="modalError"/><div v-if="fieldDraft" class="source-form"><label class="form-cell"><span class="field-label">来源字段：</span><a-select :value="`${fieldDraft.sourcePath.nodeId}|${fieldDraft.sourcePath.catalogFieldId}`" :options="fieldOptions" @change="(v:string)=>fieldSource(v,fieldDraft!)"/></label><label class="form-cell"><span class="field-label">中文名称：</span><a-input v-model:value="fieldDraft.label"/></label><label class="form-cell"><span class="field-label">稳定字段键：</span><a-input v-model:value="fieldDraft.fieldKey" :disabled="!!fieldEditId"/></label><label class="form-cell"><span class="field-label">数据分组：</span><a-input :value="fieldDraft.datasetKey??'主信息'" disabled/></label></div><div class="modal-actions"><a-button @click="fieldOpen=false">取消</a-button><a-button type="primary" @click="saveField">保存字段</a-button></div></a-modal>
 <a-modal v-model:open="metaOpen" title="单据类型元数据" :width="740" :footer="null"><a-alert type="info" message="语义变更会使草稿校验失效；已发布模板依赖将阻止语义变更。仅选择注册授权策略。"/><a-alert v-if="modalError" type="error" :message="modalError"/><div class="source-form"><label class="form-cell"><span class="field-label">单据类型：</span><a-select v-model:value="metaType" :options="choices.map(d=>({value:d.value,label:d.label}))" @change="loadMeta"/></label><label class="form-cell"><span class="field-label">读取授权：</span><a-select v-model:value="metaPolicy" :options="policies.map(p=>({value:p.policyRef,label:p.label}))" @change="metaRoots=[]"/></label><label class="form-cell"><span class="field-label">兼容主表：</span><a-select v-model:value="metaRoots" mode="multiple" :options="(policies.find(p=>p.policyRef===metaPolicy)?.compatibleMainCatalogIds??[]).map(c=>({value:c,label:catalog(c)?.label??c}))"/></label><div class="metadata-filters"><h3>固定类型筛选</h3><div v-for="(filter,index) in metaFilters" :key="index" class="filter-row"><label class="form-cell"><span class="field-label">数据表：</span><a-select v-model:value="filter.catalogId" :options="catalogs.map(c=>({value:c.catalogId,label:c.label}))" @change="filter.catalogFieldId='';filter.value=''"/></label><label class="form-cell"><span class="field-label">字段：</span><a-select v-model:value="filter.catalogFieldId" :options="(catalog(filter.catalogId)?.fields??[]).map(f=>({value:f.fieldId,label:f.label}))" @change="filter.value=''"/></label><label class="form-cell"><span class="field-label">等于：</span><a-select v-if="catalog(filter.catalogId)?.fields.find(f=>f.fieldId===filter.catalogFieldId)?.dataType==='BOOLEAN'" v-model:value="filter.value" :options="[{value:true,label:'是'},{value:false,label:'否'}]"/><a-input v-else :value="filter.value==null?'':String(filter.value)" @update:value="(v:string)=>filter.value=v"/></label><a-button danger type="link" @click="metaFilters.splice(index,1)">移除条件</a-button></div><a-button @click="metaFilters.push({catalogId:'',catalogFieldId:'',operator:'EQ',value:''})">＋ 添加固定筛选</a-button><p class="muted">只支持受控字段等值筛选，不执行用户输入表达式。</p></div><label class="form-cell"><span class="field-label">变更原因：</span><a-input v-model:value="metaReason"/></label></div><div class="modal-actions"><a-button @click="metaOpen=false">取消</a-button><a-button type="primary" :loading="busy" @click="saveMeta">保存元数据</a-button></div></a-modal>
 <a-modal v-model:open="templateOpen" title="模板中文字段预览" :width="720" :footer="null"><a-alert type="info" message="只选一个单据类型，自动读取其唯一启用数据源的已发布字段；不保存模板。"/><label class="form-cell preview-type"><span class="field-label">单据类型：</span><a-select v-model:value="templateType" :options="choices.map(d=>({value:d.value,label:d.label}))"/></label><a-alert v-if="templateError" type="error" :message="templateError"/><a-table :data-source="templateFields" row-key="key" :pagination="false" :columns="[{title:'中文名称',dataIndex:'label'},{title:'稳定字段键',dataIndex:'key'},{title:'分组',dataIndex:'group'}]"/></a-modal>
</section>
</template>
