-input,.source-form .ant-select,.source-form .ant-input-number{min-width:0;flex:1;width:100%}.source-inspector .source-form>.form-cell>.field-label{width:80px}.source-inspector{align-self:start;position:sticky;top:14px}.inspector-note,.publish-panel{border-top:1px solid #e1e8f3;padding-top:22px;margin-top:22px}.publish-panel>.ant-btn{margin-top:20px}.inspector-note p{color:#64748b;line-height:1.8}.contract-note{margin-top:20px}.metadata-filters{border:1px solid #e6edf7;padding:14px;border-radius:5px}.filter-row{display:grid;gap:12px;margin:16px 0;padding-bottom:16px;border-bottom:1px solid #e6edf7}.filter-row .ant-select,.filter-row .ant-input{flex:1;min-width:0}.modal-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:20px}.preview-type{margin:20px 0}.preview-type .ant-select{width:300px}pre{overflow:auto;max-height:320px}.source-section>.ant-alert{margin:12px 0}.source-section h3{font-size:14px;margin-top:22px}.source-workspace :deep(.selected-field td){background:#e8f2ff!important}.source-workspace :deep(.ant-table-cell){vertical-align:middle}details{margin-top:18px}@media(max-width:1100px){.source-layout{grid-template-columns:minmax(0,1fr)}.source-inspector{position:static}.source-header{flex-wrap:wrap}.type-pair{min-width:280px}}@media(max-width:650px){.source-basics{gap:16px}.type-pair{min-width:0;width:100%;flex:none}.source-header>.ant-space{flex-wrap:wrap}.source-query>.form-cell{width:100%}.source-query .ant-input,.source-query .ant-select{flex:1;width:auto}.source-steps{padding:16px}.relation-branches{margin-left:0}.source-section,.source-inspector{padding:14px}.source-query .field-label{width:75px}}
